
import os
import json
import re
import requests
from typing import List
from .base import BaseScraper, RawListing
from config import MAX_PRICE


class ImovirtualScraper(BaseScraper):
    """
    Scraper turbo para Imovirtual.com via API interna (JSON)
    """
    BASE_URL = "https://www.imovirtual.com"

    API_URL = "https://www.imovirtual.com/api/query"

    def run(self, page=None) -> List[RawListing]:
        """
        Scrape Imovirtual via API interna (JSON)
        """
        all_listings = []
        # Forçar logging detalhado
        self.logger.setLevel('DEBUG')
        cookies_path = os.path.join(os.path.dirname(__file__), '..', 'cookies_imovirtual.json')
        if not os.path.exists(cookies_path):
            self.logger.warning('cookies_imovirtual.json não encontrado. Prosseguindo sem cookies.')
            cookies = {}
        else:
            with open(cookies_path, 'r', encoding='utf-8') as f:
                cookies_list = json.load(f)
            # Converter lista de cookies para dict
            cookies = {c['name']: c['value'] for c in cookies_list if 'name' in c and 'value' in c}

        headers = {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/144.0.0.0 Safari/537.36 Edg/144.0.0.0",
            "Accept": "application/graphql-response+json, application/graphql+json, application/json, text/event-stream, multipart/mixed",
            "Referer": "https://www.imovirtual.com/pt/resultados/comprar/apartamento/porto/porto?priceMin=50000&priceMax=250000&areaMin=80&distanceRadius=5",
        }

        try:
            resp = requests.get(self.API_URL, headers=headers, cookies=cookies, timeout=30)
            resp.raise_for_status()
            data = resp.json()
        except Exception as e:
            self.logger.error(f"Erro ao obter dados da API do Imovirtual: {e}")
            return []


        # Encontrar o array de anúncios (auto-detectar campo)
        investments = None
        data_data = data.get('data', {})
        if 'searchAdsRandomInvestments' in data_data:
            investments = data_data['searchAdsRandomInvestments'].get('items')
        elif 'randomInvestments' in data_data:
            investments = data_data['randomInvestments']
        if not investments:
            self.logger.warning("Nenhum anúncio encontrado na resposta da API.")
            return []

        for ad in investments:
            try:
                listing = RawListing()
                listing.portal = "Imovirtual"
                listing.title = ad.get('name') or ad.get('title')
                # Preço
                price = ad.get('price')
                if isinstance(price, dict):
                    listing.price = str(price.get('value'))
                elif isinstance(price, (int, float, str)):
                    listing.price = str(price)
                else:
                    listing.price = None
                # Área
                area = ad.get('area')
                if isinstance(area, dict):
                    listing.area = f"{area.get('value')} m²" if area.get('value') else None
                elif isinstance(area, (int, float, str)):
                    listing.area = f"{area} m²"
                else:
                    listing.area = None
                # Localização
                loc = ad.get('location')
                if isinstance(loc, dict):
                    listing.location = loc.get('address')
                elif isinstance(loc, str):
                    listing.location = loc
                else:
                    listing.location = None
                # Link
                slug = ad.get('slug') or ad.get('id')
                if slug:
                    if str(slug).startswith('http'):
                        listing.link = slug
                    else:
                        listing.link = self.BASE_URL + slug if str(slug).startswith('/') else self.BASE_URL + '/' + str(slug)
                else:
                    listing.link = None
                # Descrição
                listing.description = ad.get('description')
                # Data
                listing.published_date = ad.get('createdAt')
                # Tipologia
                typology = ad.get('rooms') or ad.get('typology')
                if typology:
                    listing.typology = f"T{typology}"
                all_listings.append(listing)
            except Exception as e:
                self.logger.debug(f"Erro ao processar anúncio: {e}")
                continue

        self.logger.info(f"Total de anúncios extraídos via API: {len(all_listings)}")
        self.stats["listings_found"] = len(all_listings)
        return all_listings


